R=Path(__file__).resolve().parents[1];D=R/'docs/portfolio/review/menswear-direction-reset-2026-10-23'
plan=json.loads((D/'COLLECTION-PLAN.json').read_text());registry=json.loads((D/'PRODUCTION.json').read_text());byid={x['id']:x for x in plan['looks']};pilots=[x for x in registry['looks'] if x['representativeFront']]
