groups=[]
for cat in plan['categories']:
 rows=[]
 for v in [x for x in plan['looks'] if x['category']==cat['label']]:
  notes=''.join(f'<dt>{label}</dt><dd>{html.escape(v[key])}</dd>' for label,key in [('Silhouette / fit','silhouette'),('Fabric / proposed weight / drape','fabric'),('Collar','collar'),('Shoulder','shoulder'),('Sleeves','sleeves'),('Seams','seams'),('Pockets','pockets'),('Waist','waist'),('Fastenings','fastenings'),('Hem','hem'),('Colour','colour'),('Styling / footwear','styling'),('Casting / grooming','casting'),('Editorial','editorial')])
  rows.append(f"<details><summary><b>{v['position']:02d}</b> {html.escape(v['name'])} <span>{html.escape(v['product'])}</span></summary><dl>{notes}</dl><p class='muted'>Front: full-length straight-on. Back: genuine rear, preserving model, outfit, footwear and all specified construction. Sources: {', '.join(v['researchReferences'])}. Approval pending.</p></details>")
 groups.append(f"<section class='plan-group'><h3>{cat['label']} <small>10 looks</small></h3>{''.join(rows)}</section>")
