css=f'''@font-face{{font-family:Archivo;src:url({data(archivo,'font/woff2')})}}@font-face{{font-family:Inter;src:url({data(inter,'font/woff2')})}}'''+'''
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#fff;color:#191919;font-family:Inter,Arial,sans-serif;font-size:15px;line-height:1.55}main{max-width:1600px;margin:auto;padding:38px 44px 70px}a{color:inherit;text-underline-offset:4px}header{border-bottom:1px solid #d8d8d8;padding-bottom:23px}.brand{font:600 32px Archivo,Arial;letter-spacing:-1.2px}.top{display:flex;justify-content:space-between;align-items:center;gap:22px}.eyebrow{text-transform:uppercase;letter-spacing:1.7px;font-size:10px;color:#666}.approval{font-size:11px;letter-spacing:1px;text-transform:uppercase}h1{font:500 clamp(34px,4vw,60px)/1.07 Archivo,Arial;letter-spacing:-1.5px;margin:30px 0 16px;max-width:920px}header p{max-width:850px;color:#555;margin:10px 0}.nav{display:flex;gap:24px;flex-wrap:wrap;padding-top:15px;font-size:12px}.four{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:20px;margin-top:24px}figure{margin:0;min-width:0;scroll-margin-top:20px}.photo{padding:0;border:0;background:white;cursor:zoom-in;display:block;width:100%}.photo img{display:block;width:100%;height:auto;aspect-ratio:2/3;object-fit:contain}.photo:focus-visible,summary:focus-visible,a:focus-visible,dialog button:focus-visible{outline:2px solid #191919;outline-offset:5px}figcaption{padding:15px 0 22px;border-top:1px solid #ddd}h2{font:500 24px Archivo;margin:6px 0}figcaption p{margin:3px 0;font-size:12px}.muted{color:#676767}.caption{margin:12px 0 30px;max-width:1050px;color:#555;font-size:12px}.section{padding-top:35px;border-top:1px solid #d8d8d8;margin-top:35px}.section>h2{font-size:32px;margin:0 0 16px}.section>p{max-width:950px}.collection{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:30px 50px;margin-top:24px}h3{font:500 26px Archivo;margin:0 0 10px}small{font:11px Inter;color:#666;float:right;line-height:30px}details{border-top:1px solid #e1e1e1;padding:11px 0}summary{cursor:pointer;font-size:13px;line-height:1.5}summary b{font-weight:400;color:#777;margin-right:8px}summary span{display:block;color:#666;margin-left:28px;font-size:12px}dl{margin:20px 0;font-size:12px}dt{color:#666;margin-top:13px;font-size:10px;letter-spacing:.5px;text-transform:uppercase}dd{margin:3px 0}details p{font-size:12px}.assessment{max-width:1050px}.assessment p{margin:14px 0}.sources{padding-left:20px;max-width:1050px;font-size:12px}.sources li{padding:10px 0}.sources p{margin:5px 0}footer{margin-top:45px;padding-top:20px;border-top:1px solid #ddd;font-size:11px;color:#666}dialog{border:1px solid #ddd;padding:15px;max-width:94vw;max-height:96vh;background:white}dialog::backdrop{background:#0009}dialog .bar{display:flex;justify-content:space-between;gap:25px;align-items:center;font-size:12px}dialog button{border:1px solid #aaa;background:white;padding:8px 15px;color:#111;cursor:pointer}dialog img{display:block;max-width:86vw;max-height:80vh;object-fit:contain;margin:auto}body.modal{overflow:hidden}
@media(max-width:1100px){main{padding:30px}.four{gap:14px}h2{font-size:22px}.collection{gap:30px}}@media(max-width:800px){.four{grid-template-columns:repeat(2,minmax(0,1fr));gap:22px}.collection{grid-template-columns:1fr}h1{font-size:44px}.top{align-items:start}.approval{max-width:160px;text-align:right}}@media(max-width:480px){main{padding:22px 18px 45px}.brand{font-size:26px}.approval{font-size:9px;max-width:135px}h1{font-size:35px;letter-spacing:-.8px}.four{gap:18px 12px;margin-top:12px}.nav{gap:12px 18px;font-size:11px}figcaption{padding-top:10px}figcaption h2{font-size:21px}figcaption p{font-size:11px}.eyebrow{font-size:9px;letter-spacing:1px}.section>h2{font-size:28px}.section{padding-top:25px;margin-top:25px}header p{font-size:13px}.caption{font-size:11px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}@media print{main{padding:0}.photo{pointer-events:none}.four{grid-template-columns:repeat(4,1fr);gap:12px}.nav{display:none}header{padding-bottom:12px}h1{font-size:32px;margin-top:18px}.section{break-before:page}figure,details{break-inside:avoid}dialog{display:none}.collection{gap:24px}.caption{font-size:10px}}
'''
body=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ABERBACH — corrected Menswear direction</title><style>{css}</style><main><header><div class="top"><span class="brand">ABERBACH</span><span class="approval">23 October 2026<br>Owner approval pending</span></div><p class="eyebrow">Menswear 2026/2027 · original AI fashion concepts</p><h1>Four clear categories.<br>Forty distinct looks.</h1><p>Corrected merchandising and photographic direction. These four new Front candidates test commercially attractive clothes, natural young-adult casting and one premium white studio.</p><nav class="nav" aria-label="Review sections"><a href="#casualwear">Casualwear</a><a href="#activewear">Activewear</a><a href="#outerwear">Outerwear</a><a href="#tailoring">Tailoring</a><a href="#collection">Forty-look plan</a><a href="#previous">Previous pilots</a></nav></header><div class="four">{''.join(figures)}</div><p class="caption">Four separate genuine Front generations, made without image references. Click a photograph to inspect the preview. Native files: 1024 × 1536. Individual exports: 1800 × 2700, uniformly resampled. These are unapproved AI concepts; no physical manufacture or performance is established.</p><section class="section" id="collection"><p class="eyebrow">Merchandising / design / casting</p><h2>The forty-look collection</h2><p>Ten original product concepts per group. Everyday denim, jersey and knits sit alongside activity-specific sportswear, ten distinct outerwear constructions and tailoring for different occasions. Open a concept for proposed technical details and complete styling.</p><p class="muted">Four showroom labels and their route mapping await owner confirmation. Casting is natural and commercially appealing, generally adult 22–35; the clothes supply the primary variety. Weights, fibres and hidden construction below are design targets.</p><div class="collection">{''.join(groups)}</div></section><section class="section assessment" id="previous"><p class="eyebrow">Archived technical pilot / reassessed</p><h2>Previous eight looks</h2><p>All native files, 24 selected photographs, eight masters and rejected attempts remain preserved. Technical completion does not establish artistic approval.</p><p><b>Six remain candidates for later review:</b> Offset denim → Outerwear 04; Transit cargo → Casualwear 06; Airline running → Activewear 02; Baseline court → Activewear 04; Solstice linen → Casualwear 08; Rainline trench → Outerwear 09. Transit needs hardware continuity reconciliation; Rainline's Editorial hand overlaps the storm flap.</p><p><b>Two selected castings are not carried forward:</b> Strata's deliberately shaved/moustached casting and Axis's deliberately platinum buzz casting arose from forced differentiation. Their garment ideas and all files remain archived. No previous image is automatically selected for this collection.</p><p>Natural hair colour or appearance alone is not grounds for rejection. All retention decisions remain pending owner review.</p></section><section class="section" id="research"><p class="eyebrow">Commercial context / researched 23 October 2026</p><h2>Retail product evidence</h2><p>The proposed four groups are a curated showroom structure. Retail labels overlap and often use Jackets &amp; Coats or Suits &amp; Tailoring. Observed product assortments support breadth; they do not prove a universal taxonomy or a 2027 trend. Search crawl dates are not launch dates.</p><ol class="sources">{refs}</ol></section><section class="section"><p class="eyebrow">Decision gate</p><h2>Review before production</h2><p>Approval requested for the four category labels, the forty-look plan and these four actual Front photographs: clothing, fit, colour, casting, hair, styling and studio. Back and Editorial have not been produced in this reset.</p><p>After explicit approval: finish all approved looks with genuine Front / Back / Editorial, consistent models and outfits, fashionable Editorial poses and three-view masters. Current corrected status: <b>4 Front candidates, 0 owner-approved active photographs; 116 views remain unproduced.</b> This is not a completed forty-look collection.</p><p>The public Portfolio, navigation, historical links and Womenswear remain unchanged. No merge or deployment.</p></section><footer>ABERBACH / Original AI fashion concepts and visual explorations / Review only. Downloaded HTML is self-contained; no external fonts or images required.</footer></main><dialog aria-labelledby="dialog-title"><div class="bar"><span id="dialog-title"></span><button type="button" id="close">Close</button></div><img alt=""></dialog><script>const d=document.querySelector('dialog'),close=document.querySelector('#close');let opener;for(const b of document.querySelectorAll('.photo'))b.addEventListener('click',()=>{{opener=b;d.querySelector('img').src=b.querySelector('img').src;d.querySelector('img').alt=b.querySelector('img').alt;document.querySelector('#dialog-title').textContent=b.dataset.title;d.showModal();document.body.classList.add('modal');close.focus()}});close.onclick=()=>d.close();d.addEventListener('close',()=>{{document.body.classList.remove('modal');opener?.focus()}});d.addEventListener('click',e=>{{if(e.target===d)d.close()}});</script></html>'''
